// Plant name shown at the top of the dashboard (Settings page: plant_name)
msg.query = `SELECT value #>> '{}' AS name FROM mf.settings WHERE key = 'plant_name'`;
msg.params = [];
return msg;

// the template reads the column called "order" as m.order
msg.payload = msg.payload || [];
return msg;

// Latest production orders
msg.query = `
SELECT o.order_number, a.asset_code, o.part_number, o.completed_quantity, o.scrap_quantity,
       o.target_quantity, o.status, o.released_at
  FROM mf.production_orders o LEFT JOIN mf.assets a ON a.id = o.asset_id
 ORDER BY (o.status IN ('released','running')) DESC, o.released_at DESC
 LIMIT 10
`;
msg.params = [];
return msg;

const rows = msg.payload || [];
msg.payload = rows.map((o) => ({
    Order: o.order_number,
    Machine: o.asset_code,
    Part: o.part_number,
    Progress: `${o.completed_quantity} / ${o.target_quantity}`,
    Scrap: o.scrap_quantity,
    Status: o.status,
}));
return msg;

// Latest maintenance work requests
msg.query = `
SELECT r.request_number, a.asset_code, r.reason_code, r.assigned_to, r.status, r.opened_at, r.closed_at
  FROM mf.maintenance_requests r JOIN mf.assets a ON a.id = r.asset_id
 ORDER BY r.opened_at DESC, r.id DESC LIMIT 8
`;
msg.params = [];
return msg;

const t = (v) => (v ? new Date(v).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', second: '2-digit' }) : '');
msg.payload = (msg.payload || []).map((r) => ({
    Request: r.request_number,
    Machine: r.asset_code,
    Reason: r.reason_code,
    'Assigned to': r.assigned_to,
    Status: r.status,
    Opened: t(r.opened_at),
    Closed: t(r.closed_at),
}));
return msg;

// Production receipts sent back to the ERP
msg.query = `
SELECT order_number, part_number, good_quantity, scrap_quantity, received_at
  FROM demo_erp.production_receipts ORDER BY received_at DESC LIMIT 6
`;
msg.params = [];
return msg;

const t = (v) => (v ? new Date(v).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', second: '2-digit' }) : '');
msg.payload = (msg.payload || []).map((r) => ({
    Order: r.order_number, Part: r.part_number, Good: r.good_quantity, Scrap: r.scrap_quantity, Received: t(r.received_at),
}));
return msg;

// Recent notices (alerts, work requests, recoveries)
msg.query = `
SELECT n.created_at, n.severity, n.title, n.message, (n.delivered_at IS NOT NULL) AS sent
  FROM mf.notifications n ORDER BY n.created_at DESC, n.id DESC LIMIT 10
`;
msg.params = [];
return msg;

const t = (v) => (v ? new Date(v).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', second: '2-digit' }) : '');
msg.payload = (msg.payload || []).map((n) => ({
    Time: t(n.created_at), Level: n.severity, Notice: n.title, Detail: n.message, 'Sent outside': n.sent ? 'yes' : '',
}));
return msg;

// Pops up a notification on every open dashboard whenever a new alert is written.
// First run only remembers where we are, so a restart never replays old alerts.
if (flow.get('last') === undefined) {
    msg.query = 'SELECT COALESCE(max(id), 0)::int AS last FROM mf.notifications';
    msg.params = [];
    msg.init = true;
    return msg;
}
msg.query = `SELECT n.id, n.kind, n.severity, n.title, n.message, a.asset_code
               FROM mf.notifications n LEFT JOIN mf.assets a ON a.id = n.asset_id
              WHERE n.id > $1 AND NOT n.seeded ORDER BY n.id`;
msg.params = [flow.get('last')];
return msg;

const rows = msg.payload || [];
if (msg.init) { flow.set('last', rows[0] ? rows[0].last : 0); return null; }
if (!rows.length) return null;
flow.set('last', rows[rows.length - 1].id);
const COLOUR = { critical: '#dc2626', warning: '#d97706', success: '#16a34a', info: '#2563eb' };
return [rows.map((n) => ({
    payload: `${n.title}${n.message ? ': ' + n.message : ''}`,
    color: COLOUR[n.severity] || '#2563eb',
}))];

// Every setting the flows read at run time
msg.query = `
SELECT key, value, description, updated_at FROM mf.settings ORDER BY key
`;
msg.params = [];
return msg;

const t = (v) => (v ? new Date(v).toLocaleString('en-GB') : '');
msg.payload = (msg.payload || []).map((s) => ({
    Setting: s.key, Value: JSON.stringify(s.value), What: s.description, Changed: t(s.updated_at),
}));
return msg;

// Fault catalogue
msg.query = `
SELECT code, description, asset_type, severity, assigned_to, active FROM mf.reason_codes ORDER BY asset_type NULLS FIRST, code
`;
msg.params = [];
return msg;

msg.payload = (msg.payload || []).map((r) => ({
    Code: r.code, Meaning: r.description, 'Machine type': r.asset_type || 'any', Severity: r.severity,
    'Assigned to': r.assigned_to || '(default)', Active: r.active ? 'yes' : 'no',
}));
return msg;

// Machines in the plant
msg.query = `
SELECT a.asset_code, a.name, ar.name AS area, a.asset_type, a.default_part_number, a.ideal_cycle_seconds
  FROM mf.assets a LEFT JOIN mf.areas ar ON ar.id = a.area_id ORDER BY a.asset_code
`;
msg.params = [];
return msg;

msg.payload = (msg.payload || []).map((m) => ({
    Code: m.asset_code, Name: m.name, Area: m.area, Type: m.asset_type, Part: m.default_part_number, 'Cycle (s)': m.ideal_cycle_seconds,
}));
return msg;

const p = msg.payload || {};
const key = String(p.key || '').trim();
let raw = String(p.value === undefined ? '' : p.value).trim();
if (!key || raw === '') return [null, { payload: 'Both a setting name and a value are needed.', color: '#dc2626' }];
let json;
try { json = JSON.parse(raw); } catch (e) { json = raw; }   // plain words are stored as text
msg.query = `UPDATE mf.settings SET value = $2::jsonb, updated_at = now(), updated_by = 'studio' WHERE key = $1 RETURNING key`;
msg.params = [key, JSON.stringify(json)];
msg.done = `Setting "${key}" is now ${JSON.stringify(json)}. The plant picks it up within 10 seconds.`;
msg.notFound = `There is no setting called "${key}". Copy the name from the table above.`;
return [msg, null];

const ok = (msg.payload && msg.payload.length) ? true : false;
if (!ok) return [{ payload: msg.notFound || 'Nothing was changed.', color: '#d97706' }, null];
return [{ payload: msg.done, color: '#16a34a' }, { payload: 'refresh' }];

const p = msg.payload || {};
const code = String(p.code || '').trim().toUpperCase().replace(/[^A-Z0-9_]/g, '_');
const sev = String(p.severity || '').trim().toLowerCase();
if (!code || !String(p.description || '').trim()) return [null, { payload: 'A code and a description are needed.', color: '#dc2626' }];
if (!['critical', 'warning', 'info'].includes(sev)) return [null, { payload: 'Severity must be critical, warning or info.', color: '#dc2626' }];
msg.query = `INSERT INTO mf.reason_codes (code, description, asset_type, severity, assigned_to, active, updated_at)
             VALUES ($1, $2, NULLIF($3, ''), $4, NULLIF($5, ''), $6, now())
             ON CONFLICT (code) DO UPDATE SET description = EXCLUDED.description, asset_type = EXCLUDED.asset_type,
                  severity = EXCLUDED.severity, assigned_to = EXCLUDED.assigned_to, active = EXCLUDED.active, updated_at = now()
             RETURNING code`;
msg.params = [code, String(p.description).trim(), String(p.asset_type || '').trim().toLowerCase(), sev, String(p.assigned_to || '').trim(), p.active !== false];
msg.done = `Fault code ${code} saved.`;
return [msg, null];

const ok = (msg.payload && msg.payload.length) ? true : false;
if (!ok) return [{ payload: msg.notFound || 'Nothing was changed.', color: '#d97706' }, null];
return [{ payload: msg.done, color: '#16a34a' }, { payload: 'refresh' }];

const p = msg.payload || {};
const code = String(p.code || '').trim().toUpperCase();
if (!/^[A-Z0-9][A-Z0-9_-]{1,40}$/.test(code)) return [null, { payload: 'The machine code can use capitals, numbers, - and _ only.', color: '#dc2626' }];
if (!String(p.name || '').trim() || !String(p.area || '').trim() || !String(p.type || '').trim())
    return [null, { payload: 'Name, area and type are needed.', color: '#dc2626' }];
const cycle = (p.cycle === '' || p.cycle === null || p.cycle === undefined) ? null : Number(p.cycle);
if (cycle !== null && !(cycle > 0 && cycle < 100000)) return [null, { payload: 'Seconds per part must be a positive number.', color: '#dc2626' }];
msg.query = `INSERT INTO mf.areas (site_id, name) SELECT id, $1 FROM mf.sites ORDER BY created_at LIMIT 1
             ON CONFLICT (site_id, name) DO NOTHING`;
msg.params = [String(p.area).trim()];
msg.query2 = `INSERT INTO mf.assets (site_id, area_id, asset_code, name, asset_type, default_part_number, ideal_cycle_seconds)
  SELECT s.id, ar.id, $1, $2, $4, NULLIF($5, ''), $6
    FROM (SELECT id FROM mf.sites ORDER BY created_at LIMIT 1) s
    JOIN mf.areas ar ON ar.site_id = s.id AND ar.name = $3
  ON CONFLICT (site_id, asset_code) DO UPDATE SET area_id = EXCLUDED.area_id, name = EXCLUDED.name, asset_type = EXCLUDED.asset_type,
       default_part_number = EXCLUDED.default_part_number, ideal_cycle_seconds = EXCLUDED.ideal_cycle_seconds
  RETURNING asset_code`;
msg.params2 = [code, String(p.name).trim(), String(p.area).trim(), String(p.type).trim().toLowerCase(), String(p.part || '').trim(), cycle];
msg.done = `Machine ${code} saved. It shows as Offline until it sends data to mf/v1/site/<site>/asset/${code}/status.`;
return [msg, null];

msg.query = msg.query2;
msg.params = msg.params2;
return msg;

const ok = (msg.payload && msg.payload.length) ? true : false;
if (!ok) return [{ payload: msg.notFound || 'Nothing was changed.', color: '#d97706' }, null];
return [{ payload: msg.done, color: '#16a34a' }, { payload: 'refresh' }];
